import{_ as s,o as n,c as t,a2 as a}from"./chunks/framework.Zh78JZbW.js";const r="/kodus-releases/screenshots/blueprint.png",g=JSON.parse('{"title":"Blueprint et indispensables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/blueprint.md","filePath":"guide/blueprint.md"}'),i={name:"guide/blueprint.md"};function o(l,e,d,u,p,c){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="blueprint-et-indispensables" tabindex="-1">Blueprint et indispensables <a class="header-anchor" href="#blueprint-et-indispensables" aria-label="Permalink to &quot;Blueprint et indispensables&quot;">​</a></h1><p>Un <strong>blueprint</strong> est la liste du contenu d&#39;une instance (mods, shaders, packs de ressources) sous forme de texte. Collez-le dans une autre instance : Kodus y installe la version de chaque contenu compatible avec sa version de Minecraft et son loader. Idéal pour retrouver vos mods d&#39;optimisation, vos shaders et vos packs dans une instance créée pour jouer à un mod précis.</p><p><img src="'+r+`" alt="Blueprint collé dans une instance NeoForge 1.21.1 : contenus à installer, contenu sans version compatible, fichier perso"></p><h2 id="blueprint-ou-kpack" tabindex="-1">Blueprint ou .kpack ? <a class="header-anchor" href="#blueprint-ou-kpack" aria-label="Permalink to &quot;Blueprint ou .kpack ?&quot;">​</a></h2><p>Les deux servent à partager du contenu, mais pas dans le même but :</p><table tabindex="0"><thead><tr><th></th><th>Modpack <code>.kpack</code></th><th>Blueprint</th></tr></thead><tbody><tr><td>Ce que c&#39;est</td><td>Une copie <strong>exacte</strong> d&#39;une instance</td><td>Une <strong>liste</strong> de contenus, adaptée à chaque instance</td></tr><tr><td>Version de Minecraft</td><td>La même (le <code>.kpack</code> crée l&#39;instance)</td><td>N&#39;importe laquelle : Kodus cherche la bonne version de chaque contenu</td></tr><tr><td>Loader</td><td>Le même</td><td>N&#39;importe lequel (Fabric, NeoForge…), sauf les contenus qui n&#39;existent pas pour ce loader</td></tr><tr><td>Versions des mods</td><td>Identiques, au fichier près</td><td>Les plus récentes compatibles avec l&#39;instance cible</td></tr><tr><td>Réglages des mods</td><td>Inclus dans le fichier</td><td>Recopiés seulement depuis une instance de votre ordinateur</td></tr><tr><td>Mods absents de Modrinth</td><td>Inclus</td><td>Signalés, à copier à la main</td></tr><tr><td>Format</td><td>Un fichier, ouvert d&#39;un double-clic</td><td>Un texte à coller (Discord, message…)</td></tr><tr><td>Crée une instance</td><td>Oui</td><td>Non : il complète une instance existante</td></tr></tbody></table><p><strong>En pratique :</strong></p><ul><li><strong><code>.kpack</code></strong> : quand tout le monde doit avoir <strong>exactement</strong> les mêmes mods, par exemple le modpack d&#39;un serveur moddé, où la moindre différence de version empêche de se connecter. Voir <a href="./modpacks">Modpacks</a>.</li><li><strong>Blueprint</strong> : pour retrouver vos mods d&#39;optimisation, shaders et packs dans une instance d&#39;une <strong>autre version</strong>, ou conseiller une liste de mods à un ami sans lui imposer de version.</li><li><strong>Mes indispensables</strong> : un blueprint gardé par Kodus et ajouté automatiquement à chaque nouvelle instance (voir plus bas).</li></ul><h2 id="copier-un-blueprint" tabindex="-1">Copier un blueprint <a class="header-anchor" href="#copier-un-blueprint" aria-label="Permalink to &quot;Copier un blueprint&quot;">​</a></h2><p>Sur la page d&#39;une instance, cliquez sur <strong>Blueprint</strong>, puis sur <strong>Copier le blueprint</strong>. Le texte ressemble à ceci :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Kodus] Blueprint « Survie » (Fabric 1.21)</span></span>
<span class="line"><span>Mod : Sodium (sodium)</span></span>
<span class="line"><span>Mod : Iris Shaders (iris)</span></span>
<span class="line"><span>Shader : Complementary Shaders - Reimagined (complementary-reimagined)</span></span>
<span class="line"><span>Fichier perso : mon-mod.jar</span></span>
<span class="line"><span>Réglages : survie_1.21</span></span></code></pre></div><p>Vous pouvez l&#39;envoyer à un ami, ou supprimer des lignes avant de le coller. Les bibliothèques comme Fabric API n&#39;y figurent pas : Kodus les installe automatiquement quand un mod en a besoin.</p><h2 id="coller-un-blueprint" tabindex="-1">Coller un blueprint <a class="header-anchor" href="#coller-un-blueprint" aria-label="Permalink to &quot;Coller un blueprint&quot;">​</a></h2><ol><li>Ouvrez l&#39;instance cible, cliquez sur <strong>Blueprint</strong>, puis sur <strong>Coller depuis le presse-papiers</strong>.</li><li>Kodus indique, pour chaque contenu, s&#39;il sera installé, s&#39;il est déjà présent ou s&#39;il n&#39;existe pas pour cette version (par exemple un mod réservé à Fabric dans une instance NeoForge).</li><li>Décochez ce que vous ne voulez pas, puis cliquez sur <strong>Installer</strong>.</li></ol><p>Si le blueprint vient d&#39;une instance de votre ordinateur, Kodus propose aussi de <strong>recopier les réglages</strong> de ces mods et shaders (options de Sodium, shader choisi dans Iris, réglages du shader…). Les réglages déjà présents dans l&#39;instance cible ne sont jamais écrasés.</p><p>Les fichiers ajoutés à la main (introuvables sur Modrinth) sont signalés : copiez-les vous-même s&#39;ils existent pour la version de l&#39;instance.</p><h2 id="mes-indispensables" tabindex="-1">Mes indispensables <a class="header-anchor" href="#mes-indispensables" aria-label="Permalink to &quot;Mes indispensables&quot;">​</a></h2><p>Pour ne plus jamais réinstaller vos mods habituels à la main :</p><ol><li>Dans votre instance habituelle : <strong>Blueprint</strong> → <strong>Copier le blueprint</strong> → <strong>En faire mes indispensables</strong>.</li><li>Dans <strong>Paramètres</strong> → onglet <strong>Jeu</strong> → <strong>Mes indispensables</strong>, activez <strong>Les ajouter à chaque nouvelle instance</strong>.</li></ol><p>Chaque nouvelle instance, y compris celles créées par <strong>Jouer avec un mod</strong>, reçoit alors vos indispensables dans la bonne version. La fenêtre <strong>Nouvelle instance</strong> propose aussi une case pour les ajouter, ou non.</p>`,20)])])}const b=s(i,[["render",o]]);export{g as __pageData,b as default};
